parameters.jsCode:
// Platform rules used by the checks (2026 limits; tweak to taste)
const RULES = {
  'YouTube Shorts': { maxSeconds: 180, title: 100, caption: 5000, tagsMin: 1, tagsMax: 5, mustTag: '#shorts' },
  'TikTok': { maxSeconds: 600, title: 0, caption: 2200, tagsMin: 3, tagsMax: 5, mustTag: '' },
  'Instagram Reels': { maxSeconds: 180, title: 0, caption: 2200, tagsMin: 3, tagsMax: 5, mustTag: '' },
};
// Measure the script: spoken words -> seconds, hook length, hashtags, banned words, caption limits
const s = $('Set channel voice').first().json;
const items = $input.all();
return items.map((item, i) => {
  const o = item.json.output || {};
  const ctx = { topic: $('Set channel voice').first().json.topic, platform: $('Set channel voice').first().json.platform, length_seconds: $('Set channel voice').first().json.length_seconds, tone: $('Set channel voice').first().json.tone, tightened: (() => { try { return $('Tighten the script').all().length > 0; } catch (e) { return false; } })() };
  const platform = ctx.platform || 'YouTube Shorts';
  const rule = RULES[platform] || RULES['YouTube Shorts'];
  const target = Number(ctx.length_seconds) || 30;
  const wps = Number(s.words_per_second) || 2.5;
  const beats = Array.isArray(o.beats) ? o.beats : [];
  const spoken = beats.map(b => b.voiceover || '').join(' ');
  const words = spoken.split(/\s+/).filter(Boolean).length;
  const seconds = Math.round(words / wps);
  let tags = (o.hashtags || []).map(t => '#' + String(t).replace(/^#+/, '').replace(/\s+/g, '')).filter(t => t.length > 1);
  if (rule.mustTag && !tags.map(t => t.toLowerCase()).includes(rule.mustTag)) tags.unshift(rule.mustTag);
  tags = [...new Set(tags)].slice(0, rule.tagsMax);
  const banned = String(s.banned_words || '').split(',').map(b => b.trim().toLowerCase()).filter(Boolean);
  const text = `${o.title} ${spoken} ${o.caption}`.toLowerCase();
  const hit = banned.filter(b => text.includes(b));
  const issues = [];
  if (seconds > target * 1.15) issues.push(`about ${seconds}s spoken, target ${target}s`);
  if (seconds > rule.maxSeconds) issues.push(`over the ${rule.maxSeconds}s platform limit`);
  const hook = (o.hooks || [])[0] || (beats[0] || {}).voiceover || '';
  if (hook.split(/\s+/).length > 14) issues.push('hook longer than 14 words');
  if (tags.length < rule.tagsMin) issues.push(`only ${tags.length} hashtags`);
  if (rule.title && String(o.title || '').length > rule.title) issues.push(`title over ${rule.title} characters`);
  if (String(o.caption || '').length > rule.caption) issues.push(`caption over ${rule.caption} characters`);
  if (hit.length) issues.push('banned words: ' + hit.join(', '));
  const tooLong = seconds > target * 1.15;
  const script = beats.map(b => `[${b.time}] ${b.voiceover}\n   On screen: ${b.on_screen_text || '-'}\n   Visual: ${b.visual || '-'}`).join('\n');
  return { json: {
    ...ctx, title: o.title || '', hook_1: (o.hooks || [])[0] || '', hook_2: (o.hooks || [])[1] || '', hook_3: (o.hooks || [])[2] || '',
    script, beats_json: JSON.stringify(beats), caption: o.caption || '', hashtags: tags.join(' '), cta: o.cta || '',
    spoken_words: words, est_seconds: seconds, target_seconds: target,
    too_long: tooLong, issues: issues.join('; '), status: issues.length ? 'REVIEW' : 'READY',
    created_at: $now.toFormat('yyyy-MM-dd HH:mm'),
  } };
});

